from pathlib import Path
p=Path('/app')
def read(n):return list(csv.DictReader((p/n).open()))
for n in ['plan.csv','launch_log.csv','runtime.csv','eval_results.csv','retention_log.csv']:
 r=read(n); ids=[x['run_id'] for x in r]; print(n, 'rows',len(r),'unique ids',len(set(ids)))
r=read('retention_log.csv'); print('retention reasons',collections.Counter(x['reason'] for x in r)); print('lost file examples',*[x for x in r if x['reason']=='shard_file_lost'][:8],sep='\n')
launch={x['run_id']:x for x in read('launch_log.csv')}; runtime={x['run_id']:x for x in read('runtime.csv')}; ret={x['run_id']:x for x in r}; results={x['run_id']:x for x in read('eval_results.csv')}
out={i for i,x in launch.items() if x['worker'] in ('w03','w07') and '2026-06-27T00:00:00Z'<=x['started_at']<='2026-07-03T12:00:00Z'}
print('outage runs',len(out),'unexplained primary absences',set(launch)-set(results)-set(ret)-out,'outage intersect retention/results',len(out&(set(ret)|set(results))))
print('boundary starts',[x for x in launch.values() if x['started_at'] in ['2026-06-27T00:00:00Z','2026-07-03T12:00:00Z']])
print('dropped finish mismatch',[(i,x,runtime[i]) for i,x in ret.items() if x['dropped_at']!=runtime[i]['finished_at']][:5])
print('digest counts',sum(int(x['n_runs']) for x in read('daily_digest.csv')))
"],"timeout_ms":150000,"workdir":"/app"}

