from decimal import Decimal
p=pathlib.Path('/app'); plan={r['run_id']:r for r in csv.DictReader((p/'plan.csv').open())}; launch={r['run_id'] for r in csv.DictReader((p/'launch_log.csv').open())}; suites=json.loads((p/'suites.json').read_text(),parse_float=Decimal)
for shard in sorted((p/'recovered').glob('*.csv')):
 for r in csv.DictReader(shard.open()):
  s=suites[plan[r['run_id']]['suite']]; low=s['random_guess'] if s['scoring']=='raw' else 0; x=Decimal(r['pass_rate_pct'])/100
  if not low<=x<=1:print(shard.name,r,'launched',r['run_id'] in launch,'plan',plan[r['run_id']],'suite',s)
"],"timeout_ms":150000,"workdir":"/app"}
